-- SQLite baseline schema, exported from the JPA entity model. SqliteSchemaMigrator
-- runs this before the SessionFactory starts (the sqlite profile uses
-- ddl-auto: none), so it must be regenerated whenever an entity gains a table or
-- column: boot once against an empty database with
--   --spring.jpa.hibernate.ddl-auto=none
--   --spring.jpa.properties.jakarta.persistence.schema-generation.scripts.action=create
--   --spring.jpa.properties.jakarta.persistence.schema-generation.scripts.create-target=<file>
-- then prefix each statement with "if not exists". Statements stay one per line.
create table if not exists ar_payments (amount numeric(19,2) not null, drawer_movement_id bigint, employee_shift_id bigint, id integer, invoice_id bigint not null, payment_date timestamp not null, recorded_by_id bigint not null, reversed_at timestamp, payment_method varchar(30) not null default 'CASH' not null check (payment_method in ('CASH','MOBILE_WALLET','CARD','BANK_TRANSFER','CREDIT','STORE_CREDIT','OTHER')), reversal_note varchar(1000), notes varchar(255), primary key (id));
create table if not exists audit_logs (entity_id bigint, id integer, timestamp timestamp not null, user_id bigint, description varchar(1000), new_values varchar(5000), old_values varchar(5000), action varchar(255) not null, entity_type varchar(255), ip_address varchar(255), user_agent varchar(255), primary key (id));
create table if not exists backup_settings (is_enabled boolean not null, id integer, last_backup_attempt timestamp, last_backup_date timestamp, next_backup_date timestamp, scheduled_time time, google_access_token varchar(1000), google_refresh_token varchar(1000), last_error_message varchar(2000), backup_status varchar(255), custom_cron_expression varchar(255), retention_count integer default 30, anchor_day_of_month integer, frequency varchar(255) not null, primary key (id));
create table if not exists cash_drawer_movements (amount numeric(12,2) not null, drawer_session_id bigint not null, employee_shift_id bigint, id integer, occurred_at timestamp not null, performed_by bigint, reference_id bigint, movement_type varchar(30) not null check (movement_type in ('OPENING_FLOAT','CASH_SALE','CASH_REFUND','SAFE_DROP','PAY_IN','PAY_OUT','NO_SALE_OPEN','ADJUSTMENT')), reference_type varchar(40), reason varchar(1000), primary key (id));
create table if not exists cash_drawer_sessions (blind_close boolean not null default 1 not null, counted_cash numeric(12,2), expected_cash numeric(12,2), force_closed boolean not null default 0 not null, opening_float numeric(12,2) not null default 0 not null, variance_amount numeric(12,2), closed_at timestamp, closed_by bigint, created_at timestamp not null, drawer_id bigint not null, id integer, opened_at timestamp not null, opened_by bigint, updated_at timestamp, status varchar(20) not null check (status in ('OPEN','CLOSED','CANCELLED')), closing_note varchar(1000), force_close_reason varchar(1000), primary key (id));
create table if not exists cash_drawers (is_active boolean not null, created_at timestamp not null, deleted_at timestamp, id integer, code varchar(50) not null unique, name varchar(150) not null, primary key (id));
create table if not exists cash_shifts (closing_amount numeric(10,2), expected_amount numeric(10,2), force_closed boolean not null default 0 not null, opening_amount numeric(10,2) not null, variance numeric(10,2), cashier_id bigint not null, closed_by bigint, closing_time timestamp, created_at timestamp not null, drawer_session_id bigint, id integer, opening_time timestamp not null, updated_at timestamp, shift_type varchar(20) not null default 'CASH_DRAWER' not null check (shift_type in ('CASH_DRAWER','NON_CASH','SUPERVISOR')), status varchar(20) not null, force_close_reason varchar(1000), notes varchar(1000), primary key (id));
create table if not exists categories (is_active boolean not null, created_at timestamp not null, deleted_at timestamp, id integer, updated_at timestamp, version bigint, description varchar(1000), name varchar(255) not null, primary key (id));
create table if not exists count_sheet_items (client_system_quantity integer, counted_quantity integer, live_quantity_at_apply integer, system_quantity integer not null, valuation_amount numeric(19,6), variance integer, variance_at_apply integer, count_sheet_id bigint not null, counted_at timestamp, id integer, product_id bigint not null, reason_code varchar(50), note varchar(500), primary key (id));
create table if not exists count_sheets (scheduled_date date not null, variance_value numeric(19,6), approved_at timestamp, approved_by bigint, client_submitted_at timestamp, created_at timestamp not null, created_by bigint, id integer, started_at timestamp, submitted_at timestamp, submitted_by bigint, sync_received_at timestamp, updated_at timestamp, count_type varchar(30) not null check (count_type in ('ABC_A','ABC_B','ABC_C','FULL','MANUAL')), status varchar(30) not null check (status in ('DRAFT','IN_PROGRESS','PENDING_REVIEW','APPROVED','CANCELLED')), sheet_number varchar(50) not null unique, sync_key varchar(100) unique, notes varchar(1000), primary key (id));
create table if not exists customer_phones (customer_id bigint not null, id integer, phone varchar(255) not null, primary key (id));
create table if not exists customer_sequences (last_number integer not null, sequence_date date not null, id integer, primary key (id));
create table if not exists customers (credit_balance numeric(19,2), credit_limit numeric(19,2), current_balance numeric(19,2), is_active boolean not null, is_quick_add boolean, created_at timestamp not null, deleted_at timestamp, id integer, price_list_id bigint, updated_at timestamp, version bigint, address varchar(500), notes varchar(1000), city varchar(255), country varchar(255), customer_code varchar(255) not null unique, email varchar(255), first_name varchar(255) not null, last_name varchar(255) not null, phone varchar(255), state varchar(255), zip_code varchar(255), primary key (id));
create table if not exists expenses (amount numeric(10,2) not null, capitalized boolean, expense_date date not null, created_at timestamp not null, created_by bigint not null, deleted_at timestamp, settled boolean, id integer, ledger_revision BIGINT DEFAULT 0 not null, purchase_expense_id bigint, updated_at timestamp, updated_by bigint, receipt_image_type varchar(10), category varchar(50) not null check (category in ('RENT','UTILITIES','TRAVEL','TAXES','SALARY','SUPPLIES','MAINTENANCE','MARKETING','PURCHASE_VARIANCE','OTHER')), description varchar(255), receipt_image LONGBLOB, primary key (id));
create table if not exists gl_accounts (is_active boolean not null, created_at timestamp not null, id integer, code varchar(20) not null unique, account_type varchar(30) not null check (account_type in ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')), name varchar(200) not null, primary key (id));
create table if not exists gl_mappings (created_at timestamp not null, gl_account_id bigint not null, id integer, event_type varchar(50) not null check (event_type in ('CASH','ACCOUNTS_RECEIVABLE','SALES_REVENUE','SALES_DISCOUNT','SALES_TAX_PAYABLE','COST_OF_GOODS_SOLD','INVENTORY','ACCOUNTS_PAYABLE','FREIGHT_IN','OPERATING_EXPENSE','INVENTORY_REVALUATION','INVENTORY_ADJUSTMENT','EXPENSE_PAYABLE','REFUND_LIABILITY','TENDER_CLEARING','CASH_CLEARING')), description varchar(500), primary key (id));
create table if not exists inventory_ledger (qty_after integer not null, qty_delta integer not null, unit_cost numeric(19,6) not null, unit_cost_after numeric(19,6) not null, value_after numeric(19,6) not null, value_delta numeric(19,6) not null, created_by bigint, id integer, location_id bigint, occurred_at timestamp not null, posted_at timestamp not null, product_id bigint not null, source_id bigint, event_type varchar(30) not null check (event_type in ('RECEIPT','RTV','SALE','RETURN','VOID','ADJUSTMENT','COUNT','TRANSFER','REVALUATION','OPENING')), source_type varchar(40) not null, line_key varchar(60) not null, reason varchar(1000), primary key (id));
create table if not exists invoice_sequences (last_number integer, sequence_date date, id integer, primary key (id));
create table if not exists location_stock (quantity integer not null, id integer, location_id bigint not null, product_id bigint not null, updated_at timestamp, primary key (id));
create table if not exists locations (is_active boolean not null, created_at timestamp not null, id integer, updated_at timestamp, location_type varchar(30) not null check (location_type in ('SHOP','BACKROOM','QUARANTINE','TRANSIT')), code varchar(50) not null unique, name varchar(150) not null, primary key (id));
create table if not exists order_items (cost_price_at_order numeric(19,6), line_discount numeric(10,2), original_unit_price numeric(10,2), quantity integer not null, tax_amount numeric(10,2) not null, total_price numeric(10,2) not null, unit_price numeric(10,2) not null, id integer, order_id bigint not null, product_id bigint not null, promotion_id bigint, promotion_name varchar(255), primary key (id));
create table if not exists order_sequences (last_number integer, sequence_date date, id integer, primary key (id));
create table if not exists orders (discount_amount numeric(10,2), is_active boolean not null, price_list_discount numeric(10,2), promotion_discount numeric(10,2), subtotal numeric(10,2) not null, tax_amount numeric(10,2) not null, total_amount numeric(10,2) not null, cancelled_at timestamp, cancelled_by bigint, cashier_id bigint not null, converted_at timestamp, converted_sale_id bigint, created_at timestamp not null, customer_id bigint, deleted_at timestamp, id integer, updated_at timestamp, status varchar(20) not null check (status in ('PENDING','CONVERTED','CANCELLED')), cancel_reason varchar(1000), notes varchar(1000), customer_display_name varchar(255) not null, order_number varchar(255) not null unique, primary key (id));
create table if not exists period_close (frozen_cogs numeric(19,4) not null, frozen_expense numeric(19,4) not null, frozen_revenue numeric(19,4) not null, period varchar(7) not null, closed_at timestamp not null, closed_by bigint, primary key (period));
create table if not exists price_list_items (price numeric(10,2) not null, id integer, price_list_id bigint not null, product_id bigint not null, primary key (id));
create table if not exists price_lists (is_active boolean not null, valid_from date, valid_to date, created_at timestamp not null, id integer, updated_at timestamp, name varchar(150) not null unique, description varchar(1000), primary key (id));
create table if not exists product_images (display_order integer, is_primary boolean not null, created_at timestamp not null, id integer, product_id bigint not null, image_type varchar(10) not null, image_data LONGBLOB not null, primary key (id));
create table if not exists product_price_history (inventory_value_delta numeric(19,6), new_price numeric(19,6) not null, old_price numeric(19,6) not null, purchase_quantity integer, purchase_unit_price numeric(19,6), stock_qty_at_change integer, changed_at timestamp not null, changed_by bigint, id integer, product_id bigint not null, purchase_id bigint, supplier_id bigint, price_type varchar(20) check (price_type in ('SELLING','COST')), source varchar(30) check (source in ('PURCHASE_RECEIPT','PURCHASE_REVERSAL','RTV','MANUAL_ADJUSTMENT','REVALUATION','SELLING_PRICE_EDIT','OPENING_BALANCE','SALE_RETURN','LEGACY')), reason varchar(500), purchase_supplier_name varchar(255), primary key (id));
create table if not exists products (abc_class varchar(1), cost_price numeric(19,6), expiry_date date, has_expiry boolean, is_active boolean not null, last_count_date date, min_stock_level integer, reserved_quantity integer not null, stock_quantity integer not null, tax_rate numeric(5,2), unit_price numeric(10,2) not null, weight numeric(12,3), category_id bigint, created_at timestamp not null, deleted_at timestamp, id integer, updated_at timestamp, version bigint, unit varchar(50), bin_location varchar(100), description varchar(2000), barcode varchar(255), image_data LONGBLOB, image_type varchar(255), name varchar(255) not null, sku varchar(255) not null unique, thumbnail_data LONGBLOB, primary key (id));
create table if not exists profit_ledger (cogs numeric(19,4) not null, expense numeric(19,4) not null, net_revenue numeric(19,4) not null, quantity integer, settlement_ar numeric(19,4), settlement_cash numeric(19,4), settlement_clearing numeric(19,4), settlement_refund_liability numeric(19,4), tax_amount numeric(19,4) not null, period varchar(7) not null, id integer, occurred_at timestamp not null, posted_at timestamp not null, product_id bigint, source_id bigint, event_type varchar(30) not null check (event_type in ('SALE','RETURN','VOID','WRITE_OFF','EXPENSE','REVALUATION','PURCHASE_VARIANCE','INVENTORY_GAIN')), source_type varchar(40) not null, category varchar(50), settlement_account varchar(50) check (settlement_account in ('CASH','ACCOUNTS_RECEIVABLE','SALES_REVENUE','SALES_DISCOUNT','SALES_TAX_PAYABLE','COST_OF_GOODS_SOLD','INVENTORY','ACCOUNTS_PAYABLE','FREIGHT_IN','OPERATING_EXPENSE','INVENTORY_REVALUATION','INVENTORY_ADJUSTMENT','EXPENSE_PAYABLE','REFUND_LIABILITY','TENDER_CLEARING','CASH_CLEARING')), line_key varchar(60) not null, reference varchar(100), posting_key varchar(200) not null unique, primary key (id));
