create table if not exists promotions (buy_quantity integer, discount_value numeric(10,2), get_quantity integer, is_active boolean not null, min_quantity integer, priority integer not null, category_id bigint, created_at timestamp not null, end_date timestamp, id integer, product_id bigint, start_date timestamp, updated_at timestamp, scope varchar(30) not null check (scope in ('ALL','PRODUCT','CATEGORY')), type varchar(30) not null check (type in ('PERCENT_DISCOUNT','FIXED_DISCOUNT','BOGO','TIERED','FLASH_SALE')), name varchar(200) not null, description varchar(1000), primary key (id));
create table if not exists purchase_expenses (amount numeric(19,2) not null, created_at timestamp not null, id integer, purchase_id bigint not null, allocation_method varchar(30) not null check (allocation_method in ('VALUE','QUANTITY','WEIGHT')), expense_type varchar(30) not null check (expense_type in ('FREIGHT','CUSTOMS','INSURANCE','HANDLING','OTHER')), description varchar(255) not null, primary key (id));
create table if not exists purchase_items (base_unit_cost numeric(19,6), exchange_rate numeric(19,6), landed_unit_cost numeric(19,6), quantity integer not null, received_quantity integer, returned_quantity integer, total_cost numeric(10,2) not null, unit_cost numeric(19,6) not null, id integer, product_id bigint not null, purchase_id bigint not null, primary key (id));
create table if not exists purchase_payments (amount numeric(19,2) not null, drawer_movement_id bigint, employee_shift_id bigint, id integer, payment_date timestamp not null, purchase_id bigint not null, recorded_by_id bigint not null, payment_method varchar(30) not null default 'CASH' not null check (payment_method in ('CASH','MOBILE_WALLET','CARD','BANK_TRANSFER','CREDIT','STORE_CREDIT','OTHER')), notes varchar(255), primary key (id));
create table if not exists purchase_sequences (last_number integer, sequence_date date, id integer, primary key (id));
create table if not exists purchases (discount_amount numeric(10,2), exchange_rate numeric(19,6), is_active boolean not null, landed_cost_total numeric(19,2), purchase_date date not null, returned_amount numeric(19,2), subtotal numeric(10,2) not null, tax_amount numeric(10,2) not null, tax_recoverable boolean, total_amount numeric(10,2) not null, variance_amount numeric(19,2), created_at timestamp not null, created_by bigint not null, deleted_at timestamp, id integer, received_at timestamp, received_by bigint, supplier_id bigint, updated_at timestamp, currency_code varchar(10), notes varchar(1000), payment_status varchar(255) not null check (payment_status in ('PENDING','PARTIAL','PAID')), purchase_number varchar(255) not null unique, receiving_status varchar(255) check (receiving_status in ('ORDERED','PARTIAL','RECEIVED')), primary key (id));
create table if not exists receipt_customizations (bold_shop_name boolean, logo_size integer, show_address boolean, show_credit_info boolean, show_discount boolean, show_logo boolean, show_phone boolean, show_qr_code boolean, show_shop_name boolean, show_tax boolean, id integer, divider_style varchar(10), font_size varchar(10), header_align varchar(10), paper_size varchar(10), time_format varchar(10), footer_text varchar(255), header_text varchar(255), main_message varchar(255), primary key (id));
