create table if not exists system_settings (is_public boolean not null, created_at timestamp not null, id integer, updated_at timestamp, description varchar(1000), setting_value varchar(5000), data_type varchar(255) not null check (data_type in ('STRING','INTEGER','DECIMAL','BOOLEAN','JSON')), setting_key varchar(255) not null unique, primary key (id));
